"use strict";
import { useState } from "react";
import { useAccount } from "wagmi";
import { Contract } from "@ethersproject/contracts";
import { ethers } from "ethers";
import { useEthersProvider } from "hooks/useEthersProvider";
import { useQuery } from "@tanstack/react-query";
const ABSTRACT_POOL_ABI = [
  {
    inputs: [{ internalType: "address", name: "", type: "address" }],
    name: "balanceOf",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [],
    name: "index0",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [],
    name: "index1",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [{ internalType: "address", name: "", type: "address" }],
    name: "supplyIndex0",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [{ internalType: "address", name: "", type: "address" }],
    name: "supplyIndex1",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [{ internalType: "address", name: "", type: "address" }],
    name: "claimable0",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [{ internalType: "address", name: "", type: "address" }],
    name: "claimable1",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [],
    name: "tokens",
    outputs: [{ internalType: "address", name: "", type: "address" }, { internalType: "address", name: "", type: "address" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [],
    name: "claimFees",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }, { internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "nonpayable",
    type: "function"
  }
];
const ERC20_ABI = [
  {
    inputs: [],
    name: "decimals",
    outputs: [{ internalType: "uint8", name: "", type: "uint8" }],
    stateMutability: "view",
    type: "function"
  }
];
export function useAbstractV2ClaimFees({
  poolAddress,
  userAddress,
  chainId,
  enabled = true
}) {
  const { address } = useAccount();
  const provider = useEthersProvider({ chainId });
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const { data: pendingFeesData } = useQuery({
    queryKey: ["v2-pending-fees", poolAddress, userAddress, chainId],
    queryFn: async () => {
      if (!provider || !poolAddress || !userAddress) return { pendingFees0: "0", pendingFees1: "0" };
      try {
        const poolContract = new Contract(poolAddress, ABSTRACT_POOL_ABI, provider);
        const lpBalance = await poolContract.balanceOf(userAddress);
        if (lpBalance.isZero()) {
          return { pendingFees0: "0", pendingFees1: "0" };
        }
        const [
          globalIndex0,
          globalIndex1,
          userIndex0,
          userIndex1,
          alreadyClaimable0,
          alreadyClaimable1,
          [token0Address, token1Address]
        ] = await Promise.all([
          poolContract.index0(),
          poolContract.index1(),
          poolContract.supplyIndex0(userAddress),
          poolContract.supplyIndex1(userAddress),
          poolContract.claimable0(userAddress),
          poolContract.claimable1(userAddress),
          poolContract.tokens()
        ]);
        const indexDelta0 = globalIndex0.sub(userIndex0);
        const indexDelta1 = globalIndex1.sub(userIndex1);
        const WEI_PER_ETHER = ethers.constants.WeiPerEther;
        const newlyAccrued0 = lpBalance.mul(indexDelta0).div(WEI_PER_ETHER);
        const newlyAccrued1 = lpBalance.mul(indexDelta1).div(WEI_PER_ETHER);
        const totalClaimable0 = alreadyClaimable0.add(newlyAccrued0);
        const totalClaimable1 = alreadyClaimable1.add(newlyAccrued1);
        const token0Contract = new Contract(token0Address, ERC20_ABI, provider);
        const token1Contract = new Contract(token1Address, ERC20_ABI, provider);
        const [decimals0, decimals1] = await Promise.all([
          token0Contract.decimals().catch(() => 18),
          token1Contract.decimals().catch(() => 18)
        ]);
        return {
          pendingFees0: ethers.utils.formatUnits(totalClaimable0, decimals0),
          pendingFees1: ethers.utils.formatUnits(totalClaimable1, decimals1)
        };
      } catch (err) {
        console.warn("Failed to fetch V2 pending fees:", err);
        return { pendingFees0: "0", pendingFees1: "0" };
      }
    },
    enabled: enabled && !!provider && !!poolAddress && !!userAddress,
    staleTime: 1e4,
    // 10 seconds
    refetchInterval: 3e4
    // 30 seconds
  });
  const claimFees = async () => {
    if (!address || !provider || !poolAddress) {
      setError("Wallet not connected or pool not available");
      return { success: false };
    }
    setIsLoading(true);
    setError(null);
    try {
      console.log("\u{1F3AF} [CLAIM V2 FEES] Starting claim process for pool:", poolAddress);
      console.log("\u{1F3AF} [CLAIM V2 FEES] Pending fees:", pendingFeesData);
      const signer = provider.getSigner();
      const poolContract = new Contract(poolAddress, ABSTRACT_POOL_ABI, signer);
      console.log("\u{1F4B0} [CLAIM V2 FEES] Calling claimFees()...");
      const tx = await poolContract.claimFees();
      console.log("\u{1F4B0} [CLAIM V2 FEES] Transaction submitted:", tx.hash);
      await tx.wait();
      console.log("\u{1F4B0} [CLAIM V2 FEES] Transaction confirmed");
      setIsLoading(false);
      return { hash: tx.hash, success: true };
    } catch (err) {
      console.error("\u274C [CLAIM V2 FEES] Error claiming fees:", err);
      let errorMessage = "Failed to claim fees";
      if (err?.message) {
        if (err.message.includes("user rejected")) {
          errorMessage = "Transaction was cancelled by user";
        } else if (err.message.includes("insufficient funds")) {
          errorMessage = "Insufficient funds for gas";
        } else if (err.message.includes("execution reverted")) {
          errorMessage = "Transaction failed - please try again";
        } else {
          errorMessage = err.message;
        }
      }
      setError(errorMessage);
      setIsLoading(false);
      return { success: false };
    }
  };
  return {
    isLoading,
    error,
    claimFees,
    pendingFees0: pendingFeesData?.pendingFees0 || "0",
    pendingFees1: pendingFeesData?.pendingFees1 || "0"
  };
}
